          pass: { fx: [{ op: "cfavor", who: "tebrizi", v: 1 }], rZh: "木星入远方之宫。「也罢——远行人认的是同一颗木星。」", rEn: "Jupiter in the house of Exploration. 'Well then — travelers share one Jupiter.'" },
